"""Refresh the browser demo's generated styling data from the backend rules."""
import json
import sys
from pathlib import Path

root = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(root / 'backend'))
from styling import PALETTES, SILHOUETTES, SEASON_CATALOG

(root / 'frontend' / 'styling-data.js').write_text(
    '// Generated by scripts/build_styling_data.py; do not edit directly.\n'
    + 'const stylingData = ' + json.dumps({
        'palettes': PALETTES, 'silhouettes': SILHOUETTES, 'catalog': SEASON_CATALOG
    }) + ';\n'
)
